{
  "proposal": {
    "title": "住得近以后，谁能决定何时离岗？城市到岗员工的午间活动与傍晚留岗",
    "status": "保留为探索性研究候选。两起独立事件提供了提问线索。通勤缩短是否改变员工的决定权，以及这一变化是否构成学术增量，均未知。",
    "01_事件比较与概念化": {
      "E1": "据初始材料 S1 第43至46行，帖主在首份工作期间由乘地铁改为步行通勤。午间可以回家做饭、午睡，以及很少加班，均是其后来换岗并住到公司步行约五分钟处时的陈述。首份工作期间的搬近是否改变午间安排，未知。",
      "E2": "据初始材料 S2 第102至114行，受访者回忆就近居住时容易在办公室多待，日常交往也多与附近同事重叠。久留的用途、发起人、时长、能否拒绝及拒绝后果均未知。搬远涉及购房预算、居住环境与边界偏好。E2仅提供一条待查线索，现有材料无法判定其自主时间是否减少。",
      "概念判断": "活动可行性指在出行耗时、可用时段和离岗许可给定时能否完成活动。实际用途指时间最终花在哪里。决定权指谁能发起、改期或拒绝安排，以及行使这些选择会产生什么后果。员工觉得自己能拒绝、实际拒绝后发生了什么，分别记录。"
    },
    "02_问题与可反驳预测": {
      "研究问题": "对持续在同一地点、同一岗位到岗的员工，搬近何时使原本来不及的午间活动成为可行选项，何时使傍晚的临时工作变得可以接受？主管知悉员工住得近之后，员工拒绝或改期的实际余地是否随之改变？",
      "午间预测": "在午休长度和离岗许可稳定时，事先想做的居家活动只有在往返加活动所需时间落入午休窗口后才具备时间上的可行性。分别比较原本可行、搬近后首次可行和搬近后仍不可行的活动。若首次可行的活动没有更常发生，且偏好、家庭义务和替代地点不足以解释，就削弱通勤门槛对实际活动选择的解释。",
      "傍晚预测": "以请求到达时可知的预计耗时、通勤时间和事先确定的到家时点判断可行性。记录观察期内的全部请求，按任务类型、紧迫性和预计耗时比较。若到家时点是主要机制，接受率的上升应集中在搬前处理完会迟到、搬后处理完仍能准时到家的请求。若接受率在原本就来得及或搬后仍来不及的请求中也同样上升，应削弱这一解释。同时利用工作日记录比较请求到达的频率和构成，检查主管是否改变了派活方式。",
      "最强反例": "同一员工搬近后开始午间回家，也更常接受同类临时请求，但发起和改期的余地、拒绝条件及实际后果均无可核实的变化。这个结果可由常规时间约束解释，结论限于可行活动和实际用途发生变化。若观察期内没有拒绝或改期实例，其实际后果记为未知。"
    },
    "03_议题定位与观察单位": {
      "判断": "研究对象是城市到岗员工，议题是通勤条件改变后工作日安排如何形成。以员工工作日核对午间活动和傍晚留岗能否在同一人身上并存，以一次离岗机会或一次临时请求追踪安排由谁决定。",
      "全天核算": "用完整工作日记录分列早晚通勤、午间往返、留岗工作的时间及其他受影响活动。按事先规定的决定权口径计算可自主安排的分钟数，对归属未知的时段单列。午间回家次数和晚走分钟数只能各自说明局部变化。"
    },
    "04_对象_议题_理论文献对话": {
      "对象": {
        "判断": "Wang、Gong 与 Wang 已区分日工时、每周工作天数和周工时，明确讨论长工时可能促成就近居住，并在讨论部分提出工时协商能力可能解释结果差异。其分析假定纵向样本住所固定。用同岗搬迁追踪主管派活和员工拒绝，可以检验一个更具体的过程。把总工时拆到午间和傍晚属于测量细化。",
        "定位": "第2.3节式（11）、第3.6节和第4节。",
        "沿用来源": "https://www.mdpi.com/1660-4601/17/13/4631"
      },
      "议题": {
        "判断": "沿用前轮对 Giménez-Nadal 与 Velilla 的核读。该研究已用工作日日记区分有酬劳动、无酬劳动和休闲，并用不同定义检验居家办公。先用这些用途记录时间去向，再用请求和回应记录判断员工有多少选择。前轮材料表明，按用途分类本身已有先例。",
        "定位": "附表11，PDF印刷页27至28，沿用前轮定位。",
        "沿用来源": "https://www.econstor.eu/bitstream/10419/318031/1/10663_2023_Article_9590.pdf"
      },
      "理论": [
        {
          "判断": "时空地理框架已把行动能力、必须在特定时地履行的义务和制度规则放在同一解释中。午休往返门槛和固定到家时点可以纳入该框架。两条行为预测同时得到支持，只能检验这些约束在当前场景下如何共同作用。",
          "定位": "第3节图1及第3.1节。",
          "新增来源": "https://link.springer.com/article/10.1007/s10109-023-00404-1"
        },
        {
          "判断": "Kossek 与 Lautsch 已区分跨角色行为及其方向、个人感知的边界控制和组织环境，并提出组织环境影响员工能否在没有文化性惩罚的情况下实行偏好的边界安排。因此，区分留岗行为与拒绝后果有既有理论依据。",
          "定位": "印刷页155至156及图1。关于文化性惩罚的论述见网页提取版第954至984行。",
          "新增来源": "https://ellenkossek.squarespace.com/s/Work-familyboundarymanagementstylesinorganizationsAcross-levelmod.pdf"
        },
        {
          "判断": "Giunti 等对混合办公高校人员的访谈研究已区分实际做得到与在组织中被认可，并提出政策和关系方可以触发、促成或认可边界安排。将这一区分用于到岗通勤属于情境检验。更窄的待查命题是，主管是否把员工住得近当成应当留岗的理由，以及这一判断何时会改变拒绝或改期的实际后果。",
          "定位": "第1节研究贡献及第2节，网页第145至173行。",
          "新增来源": "https://onlinelibrary.wiley.com/doi/10.1002/hrm.70081"
        }
      ]
    },
    "05_抽象化与情境转换": {
      "抽象关系": "地点间移动耗时下降，可能使原本不可行的活动进入日程。若组织据此重新判断个人在某一时段应当可用，安排的决定权才可能经由请求规则和拒绝后果发生变化。",
      "情境检验": "考察工作地到固定接送点的路程缩短。按接送时点和事先承诺比较同样来得及的临时请求，追踪主管是否知悉行程变化、是否把它用作要求留岗的理由，以及员工提出改期后的实际回应。接送点只用于检验固定时点和主管知情这两个条件的适用范围。"
    },
    "06_竞争解释": [
      {
        "解释": "员工在原有决定权下重新安排时间",
        "区分判断": "若留岗接受率只在刚跨过到家时间门槛的请求中上升，且可核实的拒绝或改期条件稳定，优先采用时间约束解释。"
      },
      {
        "解释": "任务需求变化或主管重新分派",
        "区分判断": "用每个工作日的请求记录判断请求是否变多、变急或变为强制，并区分自愿继续工作与非工作性久留。主管新增派活只能说明请求机会发生变化。即使同人同岗，收到的请求也可能在搬迁后经过重新筛选。"
      },
      {
        "解释": "住房自选、家庭义务或住房条件同期改变",
        "区分判断": "核对搬迁前的住房选项、搬迁原因、既有离岗习惯和到家承诺。若留岗变化先于搬迁，或与住房品质、租购转换和照护变化同步，单靠前后比较无法归因于通勤。"
      },
      {
        "解释": "同事交往机会变化",
        "区分判断": "记录办公室内非工作活动、下班后的同事社交与实际工作。若变化集中在社交重叠，按同事交往变化解释。"
      }
    ]
  },
  "evidence_urls": [
    "https://link.springer.com/article/10.1007/s10109-023-00404-1",
    "https://ellenkossek.squarespace.com/s/Work-familyboundarymanagementstylesinorganizationsAcross-levelmod.pdf",
    "https://onlinelibrary.wiley.com/doi/10.1002/hrm.70081"
  ],
  "academic_increment": {
    "当前判断": "实质学术增量尚未成立。午间活动和傍晚留岗都变得可行，已有时间约束框架可以解释。按时段提高测量精度、转向到岗情境或更换概念名称，均不足以建立增量。",
    "待验证命题": "在同样能按时到家、请求内容与紧迫性相近的情况下，主管若把已知的就近居住作为员工理应留下的理由，员工提出改期或拒绝后，可能更容易遇到重新要求、更高的说明负担或可核实的不利后果。需要观察主管何时得知居住变化、何时开始援引距离，以及同类拒绝或改期随后如何被处理。居住信息是否被主管掌握可能与既有关系有关，仅比较知情和不知情的主管不足以确定因果。",
    "判定条件": "若只看到时间用途变化，贡献限于情境检验或测量。若观察到拒绝代价变化，还需检验它是否由任务压力或一般边界规范解释。只有过程证据支持通勤条件通过组织对可用性的具体判断改变了拒绝后果，且与最接近研究的既有命题存在可说明的区别，才考虑主张机制增量。目前直接先例及理论优先性均未知。"
  },
  "feasibility": {
    "当前材料": "现有两案可支持提出问题。可在搬迁前接触的同岗员工、可获取的排班与考勤、请求记录和拒绝后果的独立证据均未知。",
    "前瞻试采": "围绕计划搬家且保持工作地点、岗位和常规排班的员工试采，同时记录同期未搬迁的可比员工。先核查能否在搬前建立基线并取得完整工作日日记，再核查有无足够的临界请求、可比请求及自然发生的拒绝或改期。用当日记录追踪请求来由、内容、预估耗时、答复和后果。经同意可用排班、考勤或当时形成的请求记录交叉核对。考勤只能辅助核对在场时间。",
    "继续条件": "若有完整日记但缺少可比请求，只推进午间门槛和时间用途分析。若缺少可核对的拒绝或改期实例，决定权变化保持未知。若只有回顾访谈，限于过程比较。同期未搬迁者有助于识别共同变化。估计通勤缩短的因果效应仍需可辩护的距离变化来源，并查明同期的岗位、排班、住房和家庭义务是否改变。"
  },
  "limitations": [
    "S1与S2分别记录不同当事人的经历，各缺少独立记录印证。S3只提供该商业调查样本的住房偏好。原始材料的证据界限沿用，事件正文继续使用编号。",
    "本轮以每条查询和每个页面打开分别计数，共12个原生联网动作，包括5条查询、7次打开，其中3次打开失败。新增证据数组列出3个成功打开的新增页面。前轮对象文献已重开，前轮议题文献沿用已有定位。",
    "现有材料无法估计现象发生率、全天自主时间的平均净变化或因果方向。组织端机制、关键事件的招募与记录可行性、学术首创性均未知。"
  ]
}
